import{_ as a,o as i,c as t,a2 as o}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"El Índice de Disposiciones Legales","description":"","frontmatter":{},"headers":[],"relativePath":"es/92-法律条文索引.md","filePath":"es/92-法律条文索引.md","lastUpdated":1789183869000}'),d={name:"es/92-法律条文索引.md"};function s(r,e,l,n,c,u){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="el-indice-de-disposiciones-legales" tabindex="-1">El Índice de Disposiciones Legales <a class="header-anchor" href="#el-indice-de-disposiciones-legales" aria-label="Permalink to &quot;El Índice de Disposiciones Legales&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>92</td></tr><tr><td>Módulo</td><td>Apéndices y Materiales de Referencia</td></tr><tr><td>Palabras clave</td><td>índice legal, Constitución Simbiótica, ley laboral, ley de protección al consumidor, leyes complementarias</td></tr></tbody></table><h2 id="i-notas-sobre-el-indice" tabindex="-1">I. Notas sobre el Índice <a class="header-anchor" href="#i-notas-sobre-el-indice" aria-label="Permalink to &quot;I. Notas sobre el Índice&quot;">​</a></h2><p>Este índice recoge los principales documentos legales vigentes de la Civilización Simbiótica del Ancla y sus disposiciones fundamentales, organizados por jerarquía legal y departamento. El alcance del índice cubre la Constitución Simbiótica, la Ley Simbiótica del Trabajo, la Ley de Protección al Consumidor, así como las cinco leyes complementarias sobre educación, atención médica, vivienda, medio ambiente y antimonopolio. Cada entrada indica el nombre de la ley, el número de la disposición y un resumen del contenido fundamental de la disposición. Este índice es una herramienta de consulta; para el texto completo de las disposiciones legales y las interpretaciones judiciales, consulte los textos oficiales de las respectivas leyes.</p><h2 id="ii-la-constitucion-simbiotica" tabindex="-1">II. La Constitución Simbiótica <a class="header-anchor" href="#ii-la-constitucion-simbiotica" aria-label="Permalink to &quot;II. La Constitución Simbiótica&quot;">​</a></h2><p>La Constitución Simbiótica es la ley fundamental de la Civilización Simbiótica del Ancla, con la más alta fuerza jurídica, promulgada en el momento del establecimiento formal de la civilización simbiótica.</p><table tabindex="0"><thead><tr><th>N.º de Disposición</th><th>Contenido Fundamental</th></tr></thead><tbody><tr><td>Artículo 1</td><td>Establece el Universo Hengyuan (el Universo Original Wanling Hengmao) como el dominio gobernado de la Civilización Simbiótica del Ancla; el propósito fundamental de la civilización simbiótica es lograr la simbiosis de las Diez Mil Razas y la ascensión del universo</td></tr><tr><td>Artículo 2</td><td>Establece el antipredacionismo como la posición fundamental de la civilización, prohibiendo el cultivo depredador y la depredación de recursos en todas sus formas</td></tr><tr><td>Artículo 3</td><td>Establece &quot;devolver el derecho a elegir el destino y la evolución a todos los seres vivos&quot; como el concepto central de la civilización</td></tr><tr><td>Artículo 4</td><td>Establece más trabajo, más ganancia; crecimiento autónomo; un camino para cada uno; y el avance común de las Diez Mil Razas como las políticas básicas de la civilización</td></tr><tr><td>Artículo 5</td><td>Establece el sistema de apertura gratuita de los Trescientos Sistemas de Cultivo del Origen; ninguna organización o individuo puede monopolizar los derechos de transmisión de los sistemas de cultivo</td></tr><tr><td>Artículo 6</td><td>Establece el Mecanismo de Contrato Vinculado a la Producción como el sistema básico de distribución de recursos</td></tr><tr><td>Artículo 7</td><td>Establece la Estrategia de Activación del 20 % como una meta nacional por etapas</td></tr><tr><td>Artículo 8</td><td>Establece el principio de la Realidad como Fundamento: el mundo real es el único mundo real, y las configuraciones ficticias no tienen efecto legal</td></tr><tr><td>Artículo 9</td><td>Establece la Vía de Ascensión en Cuatro Etapas como la estrategia de desarrollo a largo plazo de la civilización</td></tr><tr><td>Artículo 10</td><td>Establece el principio de igualdad de las Diez Mil Razas; todas las formas de vida son iguales ante la ley</td></tr><tr><td>Artículo 11</td><td>Establece el principio de evolución simbiótica; la evolución individual no debe darse a costa de los derechos de evolución de otros individuos o colectivos</td></tr><tr><td>Artículo 12</td><td>Establece el principio de más trabajo, más ganancia; la distribución de recursos se basa en la contribución como criterio fundamental</td></tr><tr><td>Artículo 13</td><td>Establece el principio de crecimiento autónomo; se respeta el derecho de elección autónoma de evolución de cada vida</td></tr><tr><td>Artículo 14</td><td>Establece el principio de un camino para cada uno; el Estado tiene la obligación de proporcionar a cada vida un camino de evolución básico y una garantía de recursos</td></tr><tr><td>Artículo 15</td><td>Establece el principio de sostenibilidad; todo desarrollo debe tener en cuenta la sostenibilidad del origen del universo</td></tr><tr><td>Artículos 16–25</td><td>Disponen los derechos básicos de todos los seres vivos: el derecho a elegir la evolución, el derecho a obtener recursos de cultivo, el derecho a la protección igualitaria, el derecho a participar en la simbiosis, el derecho a la preservación cultural, el derecho al socorro y la apelación, el derecho a la libertad personal, el derecho a la dignidad personal, el derecho a la libertad de creencia y el derecho a la libertad de expresión</td></tr><tr><td>Artículos 26–31</td><td>Disponen las obligaciones básicas de todos los seres vivos: la obligación de cumplir la ley, de mantener el orden simbiótico, de contribuir mediante el trabajo, de proteger el medio ambiente, de respetar los derechos de los demás y de guiar a los cultivadores principiantes</td></tr><tr><td>Artículo 32</td><td>Establece la Asamblea Legislativa del Ancla como el órgano supremo de poder, compuesta por representantes de las Diez Mil Razas en proporción</td></tr><tr><td>Artículo 33</td><td>Establece el Comité Ejecutivo Simbiótico como el órgano administrativo supremo</td></tr><tr><td>Artículo 34</td><td>Establece el Tribunal Simbiótico como el órgano judicial supremo, ejerciendo independientemente el poder judicial</td></tr><tr><td>Artículo 35</td><td>Establece el Comité de Supervisión del Ancla como un órgano de supervisión independiente</td></tr><tr><td>Artículo 36</td><td>Dispone el procedimiento legislativo: un proyecto de ley se aprueba por mayoría de más de la mitad de la Asamblea Legislativa del Ancla</td></tr><tr><td>Artículo 37</td><td>Dispone el procedimiento de enmienda constitucional: debe ser aprobado por mayoría de más de dos tercios de la Asamblea Legislativa del Ancla y aprobado por más de la mitad de la población mediante referéndum</td></tr><tr><td>Artículo 38</td><td>Establece el sistema de revisión constitucional; el Tribunal Simbiótico tiene el poder de declarar nulas las leyes que violen la Constitución</td></tr><tr><td>Artículo 39</td><td>Establece el sistema de litigio constitucional; todos los seres vivos pueden iniciar directamente una acción judicial de conformidad con la Constitución</td></tr><tr><td>Artículo 40</td><td>Dispone el sistema de autonomía local; cada dominio estelar y cada plano implementan la autonomía dentro del marco de la Constitución</td></tr><tr><td>Artículo 41</td><td>Establece el sistema republicano de las Diez Mil Razas; todas las razas son iguales en la civilización simbiótica e implementan la autonomía regional</td></tr><tr><td>Artículo 42</td><td>Dispone el sistema económico de la civilización simbiótica: basado en contratos vinculados a la producción, con el desarrollo conjunto de múltiples formas de propiedad</td></tr><tr><td>Artículo 43</td><td>Dispone el sistema de propiedad estatal y distribución justa de los recursos de cultivo</td></tr><tr><td>Artículo 44</td><td>Establece el sistema de equidad educativa, garantizando el derecho igualitario a la educación de cada vida</td></tr><tr><td>Artículo 45</td><td>Establece el sistema de seguridad médica universal</td></tr><tr><td>Artículo 46</td><td>Establece el sistema de seguridad de la vivienda, garantizando el derecho básico a la vivienda de cada vida</td></tr><tr><td>Artículo 47</td><td>Dispone los principios básicos de la interacción transplanar; el viaje transplanar no autorizado está prohibido</td></tr><tr><td>Artículo 48</td><td>Dispone que los productos legítimos de las actividades arqueológicas se limitan a conocimientos e información abstractos; el retorno de materia y energía está prohibido</td></tr><tr><td>Artículo 49</td><td>Dispone los principios básicos de la regresión temporal; debe seguirse el principio de observar primero y luego intervenir dentro de límites</td></tr><tr><td>Artículo 50</td><td>Dispone que el poder de interpretar la Constitución pertenece al Tribunal Simbiótico, y el poder de enmendar la Constitución pertenece a la Asamblea Legislativa del Ancla</td></tr></tbody></table><h2 id="iii-la-ley-simbiotica-del-trabajo" tabindex="-1">III. La Ley Simbiótica del Trabajo <a class="header-anchor" href="#iii-la-ley-simbiotica-del-trabajo" aria-label="Permalink to &quot;III. La Ley Simbiótica del Trabajo&quot;">​</a></h2><p>La Ley Simbiótica del Trabajo es la ley básica que regula las relaciones laborales y protege los derechos e intereses de los trabajadores, promulgada sobre la base legislativa del Artículo 42 de la Constitución Simbiótica.</p><table tabindex="0"><thead><tr><th>N.º de Disposición</th><th>Contenido Fundamental</th></tr></thead><tbody><tr><td>Artículo 1</td><td>Propósito legislativo: regular las relaciones laborales, proteger los derechos e intereses legítimos de los trabajadores y construir relaciones laborales armoniosas y simbióticas</td></tr><tr><td>Artículo 2</td><td>Ámbito de aplicación: todas las relaciones laborales dentro del Universo Hengyuan, incluido el trabajo material, el trabajo de cultivo y el trabajo creativo</td></tr><tr><td>Artículo 3</td><td>Establece el principio de igualdad de empleo de los trabajadores; se prohíbe la discriminación laboral basada en raza, género, nivel de cultivo u origen</td></tr><tr><td>Artículo 4</td><td>Establece el principio de libre elección de empleo; se prohíben el trabajo forzoso y la esclavitud</td></tr><tr><td>Artículo 5</td><td>Dispone el sistema de contrato de trabajo; al establecer una relación laboral debe celebrarse un contrato de trabajo escrito</td></tr><tr><td>Artículo 6</td><td>Dispone las cláusulas obligatorias del contrato de trabajo: plazo del contrato, contenido del trabajo, remuneración laboral, jornada laboral, protección laboral y seguro social</td></tr><tr><td>Artículo 7</td><td>Establece la jornada laboral de ocho horas y el sistema de jornada de no más de cuarenta y cuatro horas semanales</td></tr><tr><td>Artículo 8</td><td>Dispone las restricciones de horas extraordinarias: no más de una hora diaria, tres horas en circunstancias especiales, y no más de treinta y seis horas mensuales</td></tr><tr><td>Artículo 9</td><td>Dispone las normas de pago de horas extraordinarias: 1,5 veces el salario en días laborables, 2 veces en días de descanso y 3 veces en días festivos legales</td></tr><tr><td>Artículo 10</td><td>Establece el sistema de garantía del salario mínimo; el nivel del salario mínimo lo fija cada dominio estelar según las condiciones locales</td></tr><tr><td>Artículo 11</td><td>Dispone el sistema de pago del salario: el salario debe pagarse mensualmente al trabajador personalmente en forma monetaria, sin retenciones ni retrasos injustificados</td></tr><tr><td>Artículo 12</td><td>Establece el principio de distribución de más trabajo, más ganancia; se implementa un sistema de distribución con la distribución según el trabajo como cuerpo principal y la coexistencia de múltiples métodos de distribución</td></tr><tr><td>Artículo 13</td><td>Dispone el sistema de seguridad y salud laboral; los empleadores deben proporcionar a los trabajadores condiciones de seguridad y salud laboral que cumplan las normas</td></tr><tr><td>Artículo 14</td><td>Dispone la protección de grupos especiales: se implementa protección laboral especial para trabajadores menores, trabajadoras, trabajadores con discapacidad y trabajadores de bajo nivel de cultivo</td></tr><tr><td>Artículo 15</td><td>Establece el sistema de formación profesional; los empleadores tienen la obligación de proporcionar formación profesional a los trabajadores</td></tr><tr><td>Artículo 16</td><td>Dispone los derechos laborales de los cultivadores: el trabajo de cultivo está igualmente protegido por esta Ley, y la titularidad de los resultados del cultivo se acuerda por contrato</td></tr><tr><td>Artículo 17</td><td>Establece el sistema de seguro social de los trabajadores: seguro de pensiones, seguro médico, seguro de desempleo, seguro de accidentes de trabajo y seguro de maternidad</td></tr><tr><td>Artículo 18</td><td>Dispone el sistema de bienestar de los trabajadores: los empleadores deben proporcionar a los trabajadores las prestaciones necesarias</td></tr><tr><td>Artículo 19</td><td>Establece el sistema de resolución de conflictos laborales: un mecanismo de cuatro niveles de negociación, mediación, arbitraje y litigio</td></tr><tr><td>Artículo 20</td><td>Dispone el sistema sindical; los trabajadores tienen derecho a organizar y afiliarse a sindicatos de conformidad con la ley para proteger sus derechos e intereses legítimos</td></tr><tr><td>Artículo 21</td><td>Dispone el sistema de convenio colectivo; los sindicatos representan a los trabajadores en la celebración de convenios colectivos con los empleadores</td></tr><tr><td>Artículo 22</td><td>Dispone que el reglamento interno de un empleador debe ser discutido por el congreso de trabajadores o todos los trabajadores</td></tr><tr><td>Artículo 23</td><td>Dispone las condiciones y el procedimiento de terminación de los contratos de trabajo</td></tr><tr><td>Artículo 24</td><td>Dispone el sistema de indemnización económica; los empleadores deben pagar una indemnización económica al terminar legalmente un contrato de trabajo</td></tr><tr><td>Artículo 25</td><td>Dispone el sistema de compensación por terminación ilegal del contrato de trabajo</td></tr><tr><td>Artículo 26</td><td>Establece el sistema de gestión del trabajo cedido, regulando el empleo mediante cesión de trabajadores</td></tr><tr><td>Artículo 27</td><td>Dispone las reglas especiales del trabajo a tiempo parcial</td></tr><tr><td>Artículo 28</td><td>Dispone el sistema de supervisión e inspección; los departamentos administrativos de trabajo supervisan e inspeccionan el cumplimiento de las leyes y regulaciones laborales por parte de los empleadores de conformidad con la ley</td></tr><tr><td>Artículo 29</td><td>Dispone la responsabilidad legal: los empleadores que violen esta Ley asumirán responsabilidad administrativa, civil y penal de conformidad con la ley</td></tr><tr><td>Artículo 30</td><td>Dispone la fecha de entrada en vigor y el poder de interpretación de esta Ley</td></tr></tbody></table><h2 id="iv-la-ley-de-proteccion-al-consumidor" tabindex="-1">IV. La Ley de Protección al Consumidor <a class="header-anchor" href="#iv-la-ley-de-proteccion-al-consumidor" aria-label="Permalink to &quot;IV. La Ley de Protección al Consumidor&quot;">​</a></h2><p>La Ley de Protección al Consumidor es la ley básica que protege los derechos e intereses legítimos de los consumidores y regula la conducta de los operadores económicos.</p><table tabindex="0"><thead><tr><th>N.º de Disposición</th><th>Contenido Fundamental</th></tr></thead><tbody><tr><td>Artículo 1</td><td>Propósito legislativo: proteger los derechos e intereses legítimos de los consumidores, mantener el orden económico y social y promover el desarrollo saludable de la economía de mercado simbiótica</td></tr><tr><td>Artículo 2</td><td>Ámbito de aplicación: la protección de los derechos e intereses de los consumidores dentro del Universo Hengyuan al comprar, usar mercancías o recibir servicios para las necesidades de la vida diaria</td></tr><tr><td>Artículo 3</td><td>Establece los principios básicos de las transacciones entre operadores y consumidores: voluntariedad, igualdad, equidad y buena fe</td></tr><tr><td>Artículo 4</td><td>Establece el principio de protección estatal de los derechos e intereses legítimos de los consumidores; el Estado toma medidas para garantizar que los consumidores ejerzan sus derechos de conformidad con la ley</td></tr><tr><td>Artículo 5</td><td>Dispone los nueve derechos básicos de los consumidores: derecho a la seguridad, derecho a la información, derecho a la libre elección, derecho al comercio justo, derecho a reclamar indemnización, derecho de asociación, derecho al conocimiento, derecho al respeto y derecho de supervisión</td></tr><tr><td>Artículo 6</td><td>Dispone el derecho a la seguridad del consumidor: los consumidores disfrutan del derecho a que su seguridad personal y patrimonial no sea perjudicada al comprar y usar mercancías y recibir servicios</td></tr><tr><td>Artículo 7</td><td>Dispone el derecho a la información del consumidor: los consumidores disfrutan del derecho a conocer la situación real de las mercancías que compran o usan y de los servicios que reciben</td></tr><tr><td>Artículo 8</td><td>Dispone el derecho a la libre elección del consumidor: los consumidores disfrutan del derecho a elegir libremente mercancías o servicios</td></tr><tr><td>Artículo 9</td><td>Dispone el derecho al comercio justo del consumidor: los consumidores disfrutan del derecho al comercio justo y tienen derecho a rechazar las transacciones coercitivas</td></tr><tr><td>Artículo 10</td><td>Dispone el derecho a reclamar indemnización del consumidor: los consumidores que sufran daños personales o patrimoniales por la compra y uso de mercancías o la recepción de servicios disfrutan del derecho a obtener indemnización de conformidad con la ley</td></tr><tr><td>Artículo 11</td><td>Dispone las obligaciones básicas de los operadores: cumplir las obligaciones legales y pactadas, aceptar la supervisión, garantizar la seguridad, proporcionar información veraz, emitir comprobantes, garantizar la calidad, cumplir las tres garantías, abstenerse de comercio injusto y abstenerse de vulnerar la dignidad personal</td></tr><tr><td>Artículo 12</td><td>Dispone la obligación de garantía de seguridad de los operadores: los operadores deben garantizar que las mercancías o servicios que proporcionan cumplan los requisitos de protección de la seguridad personal y patrimonial</td></tr><tr><td>Artículo 13</td><td>Dispone la obligación de divulgación de información de los operadores: los operadores deben proporcionar a los consumidores información veraz sobre las mercancías o servicios, sin publicidad falsa o engañosa</td></tr><tr><td>Artículo 14</td><td>Dispone las normas especiales para productos y servicios de cultivo: los operadores de métodos de cultivo, instrumentos de cultivo y productos energéticos deben poseer cualificaciones especiales, y los productos deben pasar la certificación de seguridad</td></tr><tr><td>Artículo 15</td><td>Dispone la regulación de las cláusulas tipo: los operadores no pueden utilizar cláusulas tipo para excluir o limitar los derechos de los consumidores, ni para mitigar o eximir la responsabilidad del operador</td></tr><tr><td>Artículo 16</td><td>Dispone el sistema de devolución sin motivo en siete días: los consumidores que compren mercancías por medios remotos como la red tienen derecho a devolverlas dentro de los siete días siguientes a la fecha de recepción</td></tr><tr><td>Artículo 17</td><td>Dispone el sistema de las tres garantías: si las mercancías o servicios proporcionados por los operadores no cumplen los requisitos de calidad, los consumidores pueden exigir reparación, sustitución o devolución de conformidad con las regulaciones nacionales</td></tr><tr><td>Artículo 18</td><td>Dispone el sistema de daños punitivos: si los operadores proporcionan mercancías o servicios con conducta fraudulenta, deben, de conformidad con los requisitos de los consumidores, aumentar la indemnización de sus pérdidas, siendo el monto del aumento tres veces el precio de las mercancías compradas o el costo de los servicios recibidos por el consumidor</td></tr><tr><td>Artículo 19</td><td>Dispone las organizaciones de consumidores: las asociaciones de consumidores y otras organizaciones de consumidores son organizaciones sociales legalmente establecidas que realizan supervisión social sobre mercancías y servicios y protegen los derechos e intereses legítimos de los consumidores</td></tr><tr><td>Artículo 20</td><td>Dispone las vías de resolución de conflictos de consumo: negociación y acuerdo con el operador, solicitud de mediación a la asociación de consumidores, reclamación ante los departamentos administrativos competentes, sometimiento a arbitraje e interposición de demanda ante el tribunal</td></tr><tr><td>Artículo 21</td><td>Dispone la inversión de la carga de la prueba en los conflictos: para mercancías duraderas o servicios como la decoración, si los consumidores descubren defectos dentro de los seis meses siguientes a la recepción, la carga de la prueba corresponde al operador</td></tr><tr><td>Artículo 22</td><td>Dispone la responsabilidad administrativa y penal de los operadores</td></tr><tr><td>Artículo 23</td><td>Dispone la fecha de entrada en vigor y el poder de interpretación de esta Ley</td></tr></tbody></table><h2 id="v-las-cinco-leyes-complementarias" tabindex="-1">V. Las Cinco Leyes Complementarias <a class="header-anchor" href="#v-las-cinco-leyes-complementarias" aria-label="Permalink to &quot;V. Las Cinco Leyes Complementarias&quot;">​</a></h2><h3 id="_5-1-la-ley-de-garantia-de-la-educacion" tabindex="-1">5.1 La Ley de Garantía de la Educación <a class="header-anchor" href="#_5-1-la-ley-de-garantia-de-la-educacion" aria-label="Permalink to &quot;5.1 La Ley de Garantía de la Educación&quot;">​</a></h3><table tabindex="0"><thead><tr><th>N.º de Disposición</th><th>Contenido Fundamental</th></tr></thead><tbody><tr><td>Artículo 1</td><td>Propósito legislativo: garantizar el derecho igualitario a la educación de todos los seres vivos, construir un sistema educativo simbiótico y promover el desarrollo común de las culturas de las Diez Mil Razas</td></tr><tr><td>Artículos 2–5</td><td>Establecen el principio de equidad educativa, el principio de educación gratuita (en la etapa de educación básica), el principio de diversidad educativa y el principio de innovación educativa</td></tr><tr><td>Artículos 6–10</td><td>Disponen la arquitectura del sistema de educación preescolar, educación obligatoria, educación secundaria superior, educación superior y educación de cultivo</td></tr><tr><td>Artículos 11–15</td><td>Disponen los sistemas especiales de la educación de cultivo: las normas pedagógicas de los Trescientos Sistemas, el sistema de tutores y el sistema de asignación de recursos de cultivo</td></tr><tr><td>Artículos 16–20</td><td>Disponen los derechos y obligaciones de los docentes, el sistema de cualificación docente y la garantía del trato docente</td></tr><tr><td>Artículos 21–25</td><td>Disponen la garantía de inversión educativa, la construcción de instalaciones educativas, la informatización educativa, la educación especial y la educación interracial</td></tr><tr><td>Artículos 26–30</td><td>Disponen el sistema de evaluación educativa, el sistema de supervisión educativa, la responsabilidad legal y las disposiciones complementarias</td></tr></tbody></table><h3 id="_5-2-la-ley-de-seguridad-medica" tabindex="-1">5.2 La Ley de Seguridad Médica <a class="header-anchor" href="#_5-2-la-ley-de-seguridad-medica" aria-label="Permalink to &quot;5.2 La Ley de Seguridad Médica&quot;">​</a></h3><table tabindex="0"><thead><tr><th>N.º de Disposición</th><th>Contenido Fundamental</th></tr></thead><tbody><tr><td>Artículo 1</td><td>Propósito legislativo: establecer un sistema de seguridad médica universal, garantizar el derecho a la salud de todos los seres vivos y mejorar el nivel de salud general de las Diez Mil Razas</td></tr><tr><td>Artículos 2–5</td><td>Establecen el principio de seguro médico universal, el principio de atención médica básica gratuita, el principio de integración de la medicina china y occidental y el principio de incorporación de la medicina de cultivo</td></tr><tr><td>Artículos 6–10</td><td>Disponen el sistema de seguro médico de múltiples niveles: seguro médico básico, seguro de enfermedades graves, asistencia médica y seguro de salud comercial</td></tr><tr><td>Artículos 11–15</td><td>Disponen la gestión de las instituciones médicas, el sistema del personal médico, la calidad y seguridad médicas y las normas especiales de la medicina de cultivo</td></tr><tr><td>Artículos 16–20</td><td>Disponen la gestión de medicamentos, la gestión de dispositivos médicos, la gestión de productos médicos energéticos y el sistema de medicamentos esenciales</td></tr><tr><td>Artículos 21–25</td><td>Disponen el sistema de salud pública, la prevención y el control de enfermedades, la educación sanitaria, la atención médica interracial y la seguridad médica de grupos especiales</td></tr><tr><td>Artículos 26–30</td><td>Disponen el tratamiento de conflictos médicos, la supervisión médica, la responsabilidad legal y las disposiciones complementarias</td></tr></tbody></table><h3 id="_5-3-la-ley-de-seguridad-de-la-vivienda" tabindex="-1">5.3 La Ley de Seguridad de la Vivienda <a class="header-anchor" href="#_5-3-la-ley-de-seguridad-de-la-vivienda" aria-label="Permalink to &quot;5.3 La Ley de Seguridad de la Vivienda&quot;">​</a></h3><table tabindex="0"><thead><tr><th>N.º de Disposición</th><th>Contenido Fundamental</th></tr></thead><tbody><tr><td>Artículo 1</td><td>Propósito legislativo: garantizar el derecho básico a la vivienda de todos los seres vivos, construir un sistema de seguridad de la vivienda de múltiples niveles y lograr vivienda para todos</td></tr><tr><td>Artículos 2–5</td><td>Establecen el principio de garantía del derecho a la vivienda, el principio de equidad de la vivienda, el principio de alquiler y compra conjuntos y el principio de vivienda sostenible</td></tr><tr><td>Artículos 6–10</td><td>Disponen el sistema de oferta de vivienda: viviendas de alquiler público, viviendas de alquiler protegido, viviendas de propiedad compartida y viviendas comerciales</td></tr><tr><td>Artículos 11–15</td><td>Disponen el sistema del fondo de vivienda, el sistema de subsidios de vivienda, las políticas de apoyo a la primera vivienda y las políticas especiales de vivienda para cultivadores</td></tr><tr><td>Artículos 16–20</td><td>Disponen las normas de construcción de viviendas, la aplicación de la tecnología espacial en la vivienda, los edificios verdes y las viviendas adaptadas a personas mayores y sin barreras</td></tr><tr><td>Artículos 21–25</td><td>Disponen la regulación del mercado inmobiliario, las normas del mercado de alquiler, la gestión de servicios inmobiliarios y la garantía de mantenimiento de la vivienda</td></tr><tr><td>Artículos 26–30</td><td>Disponen la supervisión de la seguridad de la vivienda, la responsabilidad legal y las disposiciones complementarias</td></tr></tbody></table><h3 id="_5-4-la-ley-de-proteccion-del-medio-ambiente" tabindex="-1">5.4 La Ley de Protección del Medio Ambiente <a class="header-anchor" href="#_5-4-la-ley-de-proteccion-del-medio-ambiente" aria-label="Permalink to &quot;5.4 La Ley de Protección del Medio Ambiente&quot;">​</a></h3><table tabindex="0"><thead><tr><th>N.º de Disposición</th><th>Contenido Fundamental</th></tr></thead><tbody><tr><td>Artículo 1</td><td>Propósito legislativo: proteger y mejorar el medio ambiente, prevenir y controlar la contaminación y otras amenazas públicas, garantizar la salud pública, promover la construcción de la civilización ecológica cósmica y avanzar hacia el desarrollo sostenible</td></tr><tr><td>Artículos 2–5</td><td>Establecen el principio de prioridad de la protección, el principio de prevención primaria, el principio de tratamiento integral, el principio de participación pública y el principio de responsabilidad por los daños</td></tr><tr><td>Artículos 6–10</td><td>Disponen el sistema de supervisión y gestión ambiental, el sistema de normas ambientales, el sistema de evaluación de impacto ambiental, el sistema de monitoreo ambiental y la gestión ambiental transplanar</td></tr><tr><td>Artículos 11–15</td><td>Disponen la prevención y el control de la contaminación del aire, del agua, del suelo, de la contaminación energética y de la contaminación de leyes</td></tr><tr><td>Artículos 16–20</td><td>Disponen el tratamiento de residuos sólidos, la prevención y el control de la contaminación acústica, de la contaminación radiactiva, la protección ecológica y la protección de la biodiversidad</td></tr><tr><td>Artículos 21–25</td><td>Disponen el control del impacto ambiental de las actividades de cultivo, la protección ecológica de la extracción de energía y los requisitos ambientales de la arqueología transplanar</td></tr><tr><td>Artículos 26–30</td><td>Disponen la divulgación de información y la participación pública, la acción de interés público ambiental, la responsabilidad legal y las disposiciones complementarias</td></tr></tbody></table><h3 id="_5-5-la-ley-antimonopolio" tabindex="-1">5.5 La Ley Antimonopolio <a class="header-anchor" href="#_5-5-la-ley-antimonopolio" aria-label="Permalink to &quot;5.5 La Ley Antimonopolio&quot;">​</a></h3><table tabindex="0"><thead><tr><th>N.º de Disposición</th><th>Contenido Fundamental</th></tr></thead><tbody><tr><td>Artículo 1</td><td>Propósito legislativo: prevenir y detener las conductas monopolísticas, proteger la competencia leal del mercado, mejorar la eficiencia del funcionamiento económico, salvaguardar los intereses de los consumidores y el interés público social y promover el desarrollo saludable de la economía de mercado simbiótica</td></tr><tr><td>Artículos 2–5</td><td>Establecen la posición fundamental de la política de competencia, el sistema de revisión de competencia leal, la prohibición de acuerdos monopolísticos, la prohibición del abuso de posición dominante en el mercado y el control de la concentración de empresas</td></tr><tr><td>Artículos 6–10</td><td>Disponen la determinación y exención de acuerdos monopolísticos, los acuerdos monopolísticos horizontales, los acuerdos monopolísticos verticales y las conductas monopolísticas de las asociaciones industriales</td></tr><tr><td>Artículos 11–15</td><td>Disponen la determinación de la posición dominante en el mercado, los tipos de conductas constitutivas de abuso de posición dominante y la prohibición de precios predatorios</td></tr><tr><td>Artículos 16–20</td><td>Disponen los estándares de notificación de la concentración de empresas, el procedimiento de revisión, las condiciones restrictivas adicionales y las decisiones de prohibición de la concentración</td></tr><tr><td>Artículos 21–25</td><td>Disponen la prohibición especial del monopolio en los sistemas de cultivo: prohibición de monopolizar los métodos de cultivo, prohibición de monopolizar los recursos de cultivo y prohibición de monopolizar las redes de tutores</td></tr><tr><td>Artículos 26–30</td><td>Disponen la autoridad de aplicación de la ley antimonopolio, el procedimiento de investigación, la responsabilidad legal, el sistema de indulgencia y las disposiciones complementarias</td></tr></tbody></table><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>El índice de disposiciones legales es el mapa de consulta del sistema de estado de derecho de la Civilización Simbiótica del Ancla. Desde la Constitución Simbiótica como ley fundamental, pasando por la Ley del Trabajo y la Ley de Protección al Consumidor que regulan el bienestar del pueblo, hasta las cinco leyes complementarias, juntas constituyen un sistema legal completo &quot;con la Constitución como comandante, las leyes básicas como columna vertebral y las leyes complementarias como apoyo&quot;. Este sistema garantiza que todas las actividades de la civilización simbiótica operen en la vía del estado de derecho, proporcionando una sólida garantía institucional para el avance común de las Diez Mil Razas.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Constitución Simbiótica: Principios Generales)</li><li>41-共生劳动法 (Ley Simbiótica del Trabajo)</li><li>48-司法体系与裁决机制 (Sistema Judicial y Mecanismo de Adjudicación)</li></ul>',28)])])}const b=a(d,[["render",s]]);export{p as __pageData,b as default};
